                        f.write("\n".join([f"Línea {i}" for i in range(300)]))
                elif nombre == "medios.json":
                    with open(file_path, "w", encoding="utf-8") as f:
                        json.dump({"medios": ["oracle-a1"]}, f)
                elif nombre == "puntos-control.json":
